const pageSecrets={museum:[['tooth','A tiny fossil tooth! Gizmo is ready for a shark mystery.'],['pearl','A pearl was hiding in the reef. What a careful explorer!']],expeditions:[['compass','The little compass spins. Your next adventure is waiting!'],['bottle','A message from Milo: Have a go. I’m proud of your trying!']],play:[['jelly','A tiny jellyfish does a wobbly dance for you!'],['star','A shy sea star peeks out. Hello, Haytham!']],writing:[['bottle','A little ocean note: Every mark is a new beginning.'],['pearl','Dash found a shining pearl. Slow and steady, one stroke at a time!']],stories:[['lantern','A story lantern glows. What might be hiding in the next chapter?'],['star','A sea star has saved your place in the story!']],legend:[['bottle','A pirate’s note says: This kraken is a make-believe sea legend!'],['lantern','A little lantern lights the cave. What a brave explorer!']],collection:[['key','A tiny treasure key! What might it open in your imagination?'],['pearl','A rainbow pearl glimmers in your reef. You found it!']],cinema:[['star','A sea star has come to watch the film too!'],['pearl','A secret pearl lights up. The best seat is beside your friend.']]};
function secretIcon(kind){const shapes={tooth:'<path d="M31 5L49 44Q32 51 13 44Z" fill="#f0e5c5" stroke="#b5a075" stroke-width="2"/><path d="M13 44L8 52H54L49 44" stroke="#b5a075" stroke-width="4"/>',pearl:'<path d="M7 38Q32 54 57 38Q53 61 32 59Q10 60 7 38Z" fill="#b0ded5" stroke="#e4e5c0" stroke-width="2"/><circle cx="32" cy="29" r="15" fill="#f3dfef" stroke="#d5edf1" stroke-width="2"/><circle cx="27" cy="24" r="5" fill="#fff9ee" opacity=".8"/>',bottle:'<path d="M25 7H39V19L47 29V54Q32 61 17 54V29L25 19Z" fill="#a1dcd5" fill-opacity=".7" stroke="#d4ede5" stroke-width="2"/><path d="M24 7H40M24 12H40" stroke="#d4ae6a" stroke-width="5"/><path d="M24 29H41V48H24Z" fill="#f4e2b3"/><path d="M28 34H37M28 40H37" stroke="#887655" stroke-width="2"/>',jelly:'<path d="M10 32Q9 7 32 7Q55 7 54 32Q43 39 32 32Q21 39 10 32" fill="#d8b1e8" stroke="#e6d8f0" stroke-width="2"/><path d="M16 35Q10 43 18 53M28 36Q21 48 29 58M40 36Q32 45 41 57M50 35Q44 44 51 52" fill="none" stroke="#b8e5de" stroke-width="3"/><circle cx="24" cy="25" r="2" fill="#264a67"/><circle cx="40" cy="25" r="2" fill="#264a67"/>',star:'<path d="M32 5L39 23L59 23L44 36L49 56L32 45L15 56L20 36L5 23H25Z" fill="#e9ba76" stroke="#f5e0b4" stroke-width="2"/><circle cx="27" cy="31" r="2" fill="#54636a"/><circle cx="37" cy="31" r="2" fill="#54636a"/>',key:'<circle cx="22" cy="20" r="12" fill="none" stroke="#eed38e" stroke-width="7"/><path d="M31 29L53 51M44 43L37 50M50 49L44 56" stroke="#eed38e" stroke-width="7"/>',lantern:'<path d="M21 17Q18 4 32 4Q46 4 43 17M18 20H46L43 53H21Z" fill="#e1c680" stroke="#a29a79" stroke-width="3"/><path d="M25 25H39V45H25Z" fill="#fff2be"/><path d="M17 55H47" stroke="#c8b78c" stroke-width="4"/>',compass:'<circle cx="32" cy="32" r="23" fill="#cde8de" fill-opacity=".3" stroke="#e7d4a2" stroke-width="3"/><path d="M43 19L37 37L20 45L27 27Z" fill="#edd7a3"/><circle cx="32" cy="32" r="3" fill="#51787f"/>'};return `<svg viewBox="0 0 64 64" aria-hidden="true">${shapes[kind]||shapes.star}</svg>`}
function syncSecrets(){const route=(location.hash.slice(1)||'home').split('/')[0];if(!pageSecrets[route])return;if($('#oceanSecrets'))return;const trail=document.createElement('aside');trail.id='oceanSecrets';trail.className='ocean-secret-trail';trail.setAttribute('aria-label','Floating ocean secrets');trail.innerHTML=pageSecrets[route].map(([kind],i)=>`<button class="ocean-secret secret-${i}" data-secret="${i}" aria-label="Explore the floating ${kind}">${secretIcon(kind)}</button>`).join('');trail.addEventListener('click',e=>{const button=e.target.closest('[data-secret]');if(!button)return;stopStory();const index=+button.dataset.secret,[kind,message]=pageSecrets[route][index];state.oceanSecrets=state.oceanSecrets||[];const key=route+'-'+kind;if(!state.oceanSecrets.includes(key)){state.oceanSecrets.push(key);save()}button.classList.remove('secret-found');void button.offsetWidth;button.classList.add('secret-found');$('#secretMessage')?.remove();const note=document.createElement('p');note.id='secretMessage';note.className='secret-message';note.setAttribute('role','status');note.textContent=message;trail.append(note);setTimeout(()=>note.remove(),6500);reactCrew('happy');helperSpeak(message)});app.prepend(trail)}
